using Azure.Storage.Blobs;
using Azure.Storage.Blobs.Models;

string connectionString = "DefaultEndpointsProtocol=https;AccountName=...;AccountKey=...;EndpointSuffix=core.windows.net";

// Create the service client
BlobServiceClient serviceClient = new BlobServiceClient(connectionString);

// Create a container client
BlobContainerClient container = serviceClient.GetBlobContainerClient("my-container");
await container.CreateIfNotExistsAsync();

// Upload a blob
BlobClient blob = container.GetBlobClient("hello.txt");
await blob.UploadAsync(BinaryData.FromString("Hello from .NET!"));
Console.WriteLine($"Uploaded: {blob.Uri}");

// Download a blob
BlobDownloadResult download = await blob.DownloadContentAsync();
Console.WriteLine(download.Content.ToString());

// List blobs in a container
await foreach (BlobItem item in container.GetBlobsAsync())
{
    Console.WriteLine(item.Name);
}

BlobSasBuilder sas = new BlobSasBuilder
{
    BlobContainerName = "my-container",
    BlobName = "hello.txt",
    Resource = "b",
    StartsOn = DateTimeOffset.UtcNow,
    ExpiresOn = DateTimeOffset.UtcNow.AddHours(1)
};

sas.SetPermissions(BlobSasPermissions.Read);

Uri sasUri = blob.GenerateSasUri(sas);
Console.WriteLine(sasUri);
